import type { ComponentProps, MouseEventHandler } from 'react'
import { mergeProps } from '@base-ui/react/merge-props'
import { useRender } from '@base-ui/react/use-render'
import { cn } from '@/lib/utils'
import styles from './Card.module.css'

export interface CardProps extends Omit<ComponentProps<'div'>, 'onClick'> {
  /** Padding and the gap between children. */
  size?: 'xs' | 'sm' | 'md' | 'lg'
  appearance?: 'elevated' | 'outline' | 'filled' | 'unstyled'
  /** How children flow: stacked, or side by side (e.g. media and text). */
  orientation?: 'vertical' | 'horizontal'
  isRounded?: boolean
  hasBorder?: boolean
  /** Makes the whole card a `<button>`. Its content must then be non-interactive. */
  onClick?: MouseEventHandler<HTMLElement>
  /** Replaces the element — `<a href>` or a router's Link for a card that navigates. */
  render?: useRender.RenderProp
}

export function Card({
  size = 'sm',
  appearance = 'elevated',
  orientation = 'vertical',
  isRounded = true,
  hasBorder = true,
  onClick,
  render,
  className,
  ...props
}: CardProps) {
  // render is for link cards (see the MDX), so it counts as interactive.
  const interactive = onClick !== undefined || render !== undefined
  return useRender({
    render,
    defaultTagName: onClick ? 'button' : 'div',
    props: mergeProps<'div'>(
      {
        className: cn(
          styles.card,
          styles[size],
          styles[appearance],
          styles[orientation],
          isRounded && styles.rounded,
          hasBorder && appearance !== 'unstyled' && styles.bordered,
          interactive && styles.interactive,
          className,
        ),
        // type only on the <button> this renders itself, never on a render element.
        ...(onClick && { onClick, ...(!render && { type: 'button' }) }),
      } as ComponentProps<'div'>,
      props,
    ),
  })
}

.card {
  display: flex;
  box-sizing: border-box;
  margin: 0;
  border: 1px solid transparent;
  background: transparent;
  color: var(--card-foreground);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  text-align: start;
  text-decoration: none;
}

.vertical {
  flex-direction: column;
}

.horizontal {
  flex-direction: row;
  align-items: flex-start;
}

.xs {
  gap: var(--space-2);
  padding: var(--space-3);
}
.sm {
  gap: var(--space-3);
  padding: var(--space-4);
}
.md {
  gap: var(--space-4);
  padding: var(--space-6);
}
.lg {
  gap: var(--space-6);
  padding: var(--space-8);
}

.rounded {
  border-radius: var(--radius-panel);
}

/* The card's own border is the non-interactive one; a clickable card still
   uses it, and shows its interactivity by hover and focus instead. */
.bordered {
  border-color: var(--border);
}

.elevated {
  background: var(--card);
  box-shadow: var(--shadow-sm);
}

.outline {
  background: var(--card);
}

/* Not --muted: muted text reads 4.81:1 on the subtle surface against
   4.60:1 on --muted, the tighter margin. */
.filled {
  background: var(--surface-subtle);
}

/* unstyled keeps its padding and layout, and drops everything you see. */
.unstyled {
  color: inherit;
}

button.interactive {
  cursor: var(--cursor-button);
}

.interactive {
  transition:
    background-color 150ms,
    box-shadow 150ms;
}

a[href].interactive {
  cursor: var(--cursor-link);
}

/* Hover never touches the surface: muted text sits on it at 4.5:1 with no
   margin to spare (darkening it 6% took muted text to 3.9:1). Elevated
   lifts to a larger shadow; the others strengthen their edge to the 3:1
   control border. */
.elevated.interactive:hover {
  box-shadow: var(--shadow-md);
}

.outline.interactive:hover,
.filled.interactive:hover {
  border-color: var(--control-border);
}

.interactive:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
